package cn.local.rainreminder;
import android.app.*;import android.appwidget.*;import android.content.*;import android.os.*;import android.view.View;import android.widget.*;import java.time.*;import java.util.*;

public class RainWidget extends AppWidgetProvider {
 static final String REFRESH="cn.local.rainreminder.WIDGET_REFRESH";
 static PendingIntent tick(Context c){return PendingIntent.getBroadcast(c,7310,new Intent(c,RainWidget.class).setAction(REFRESH),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static final String MENU="cn.local.rainreminder.WIDGET_MENU";
 static PendingIntent menu(Context c,int id){return PendingIntent.getBroadcast(c,0,new Intent(c,RainWidget.class).setAction(MENU).setData(android.net.Uri.parse("rainwidget://menu/"+id)).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static final String SWITCH="cn.local.rainreminder.WIDGET_SWITCH";
 static PendingIntent switchDisplay(Context c,int id,int mode,int style){Intent intent=new Intent(c,RainWidget.class).setAction(SWITCH).setData(android.net.Uri.parse("rainwidget://switch/"+id+"/"+mode+"/"+style)).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).putExtra("mode",mode).putExtra("style",style);return PendingIntent.getBroadcast(c,0,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static final String CHECK="cn.local.rainreminder.WIDGET_CHECK_HOMEWORK";
 static PendingIntent checkHomework(Context c){return PendingIntent.getBroadcast(c,7312,new Intent(c,RainWidget.class).setAction(CHECK),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent issue(Context c){return PendingIntent.getActivity(c,7313,new Intent(c,MainActivity.class).setData(android.net.Uri.parse("rainwidget://homework/issue")).putExtra("widgetShowError",true).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent open(Context c,Class<?> page,int id,long day){Intent intent=new Intent(c,page).setData(android.net.Uri.parse("rainwidget://"+page.getSimpleName()+"/"+id)).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);if(day>0)intent.putExtra("widgetDay",day);return PendingIntent.getActivity(c,id,intent,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static PendingIntent settings(Context c,int id){Intent i=new Intent(c,WidgetSettingsActivity.class).setData(android.net.Uri.parse("rainwidget://settings/"+id)).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK);return PendingIntent.getActivity(c,7520+id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static RemoteViews views(Context c,int id,int height,long now){return views(c,id,height,now,WidgetOptions.mode(c,id));}
 static RemoteViews views(Context c,int id,int height,long now,int mode){return views(c,id,height,now,mode,WidgetOptions.style(c,id));}
 static RemoteViews views(Context c,int id,int height,long now,int mode,int style){
  long last=Store.prefs(c).getLong("last",0);WidgetData.Snapshot data=WidgetData.build(Agenda.all(c),HomeworkDisplay.visible(c),last,now);
  int hiddenCount=HomeworkDisplay.dimmed(c).length();if(hiddenCount>0){if(HomeworkDisplay.visible(c).length()==0)data.homework="作业 · 已全部淡化";data.hint+=" · "+hiddenCount+"项已淡化";}boolean homework=WidgetOptions.homeworkFirst(mode),secondary=WidgetOptions.both(mode);
  RemoteViews views=new RemoteViews(c.getPackageName(),mode==WidgetOptions.HOMEWORK_FIRST?(HomeworkDisplay.visible(c).length()==0?R.layout.rain_widget_homework_empty_v33:R.layout.rain_widget_homework_v33):R.layout.rain_widget_v32);views.setViewVisibility(R.id.widget_rows,View.VISIBLE);views.setViewVisibility(R.id.widget_day_nav,View.GONE);views.setViewVisibility(R.id.widget_day_grid,View.GONE);views.setImageViewBitmap(R.id.widget_day_grid,null);views.setViewVisibility(R.id.widget_primary_list,View.GONE);views.setViewVisibility(R.id.widget_secondary_list,View.GONE);views.setViewVisibility(R.id.widget_day_pages,View.GONE);views.setViewVisibility(R.id.widget_week_header,View.GONE);views.setImageViewBitmap(R.id.widget_week_header,null);views.setViewVisibility(R.id.widget_secondary_nav,View.GONE);
  PendingIntent agenda=open(c,AgendaActivity.class,7320+id,data.date.toEpochDay()),jobs=open(c,MainActivity.class,7420+id,0),primary=homework?jobs:agenda;
  views.setOnClickPendingIntent(R.id.widget_root,null);views.setOnClickPendingIntent(R.id.widget_heading,primary);
  views.setViewVisibility(R.id.widget_footer,secondary?View.VISIBLE:View.GONE);views.setViewVisibility(R.id.widget_homework_hint,height<190?View.GONE:View.VISIBLE);views.setViewVisibility(R.id.widget_date,height<150?View.GONE:View.VISIBLE);views.removeAllViews(R.id.widget_rows);
  int limit=secondary?(height>=270?3:height>=215?2:1):(height>=250?3:height>=190?2:1);
  if(homework){
   org.json.JSONArray tasks=Deadlines.sorted(HomeworkDisplay.visible(c));views.setTextViewText(R.id.widget_heading,last>0?"待交作业 · "+tasks.length()+"项":"作业提醒");
   String date=last>0?"上次检查 · "+java.time.Instant.ofEpochMilli(last).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("MM-dd HH:mm")):"请先登录并检查作业";
   if(Scanner.running()||WidgetCheckJob.pending(c))date=Store.prefs(c).getString("widgetProgress","正在检查，保留上次结果");
   views.setTextViewText(R.id.widget_date,date);bindHomework(c,views,R.id.widget_refresh);
   if(last<=0)addRow(c,views,"登录后查看待交作业","点击进入作业页",jobs,height,false);
   else if(tasks.length()==0)addRow(c,views,hiddenCount>0?"暂无需要显示的作业":"暂无待交作业",hiddenCount>0?hiddenCount+"项已在作业页底部淡化显示":"以上次成功检查为准",jobs,height,false);
   else for(int n=0;n<Math.min(limit,tasks.length());n++){org.json.JSONObject task=tasks.optJSONObject(n);String course=task.optString("course");addRow(c,views,task.optString("title"),Deadlines.label(task)+(course.isEmpty()?"":" · "+course),jobs,height,false);}
   views.setOnClickPendingIntent(R.id.widget_homework_area,agenda);views.setTextViewText(R.id.widget_homework,data.items.isEmpty()?"近期没有后续安排":"下一项 · "+data.items.get(0).event.optString("title"));views.setTextViewText(R.id.widget_homework_hint,data.items.isEmpty()?"点击进入课表":data.subtitle+" · "+WidgetData.detail(data.items.get(0),now));bindSchedule(c,views,R.id.widget_check_homework);
  }else{
   views.setTextViewText(R.id.widget_heading,data.heading);views.setTextViewText(R.id.widget_date,data.subtitle);bindSchedule(c,views,R.id.widget_refresh);
   for(int n=0;n<Math.min(limit,data.items.size());n++){WeekTable.Item item=data.items.get(n);String title=(n==0&&item.start>now?"下一项 · ":"")+item.event.optString("title");if(height<190)title=java.time.Instant.ofEpochMilli(item.start).atZone(java.time.ZoneId.systemDefault()).format(java.time.format.DateTimeFormatter.ofPattern("HH:mm"))+" · "+item.event.optString("title");addRow(c,views,title,WidgetData.detail(item,now),agenda,height,true);}
   if(data.items.isEmpty())addRow(c,views,Agenda.all(c).length()==0?"还没有课表或日程":"近期没有后续安排","点击进入课表，导入截图或添加安排",agenda,height,true);
   views.setOnClickPendingIntent(R.id.widget_homework_area,jobs);views.setTextViewText(R.id.widget_homework,data.homework);String hint=data.hint;
   if(Scanner.running()||WidgetCheckJob.pending(c))hint=Store.prefs(c).getString("widgetProgress","正在联网检查，保留上次结果");else if(Store.prefs(c).getString("status","").startsWith("检查失败"))hint="检查未完成，保留上次结果";
   views.setTextViewText(R.id.widget_homework_hint,hint);bindHomework(c,views,R.id.widget_check_homework);
  }
  if(!homework&&style==1)WidgetDayTable.bind(c,views,id,height,now,secondary);
  if(!homework&&style==0){views.setTextViewText(R.id.widget_heading,"当天课程");views.setTextViewText(R.id.widget_date,"上下滑动查看课程");WidgetDateNav.bind(c,views,id,false,false,now);}
  if(homework||style==0){views.setViewVisibility(R.id.widget_rows,View.GONE);WidgetLists.bind(c,views,id,R.id.widget_primary_list,homework,now);}
  if(secondary){boolean compact=!homework&&height<330;views.setViewVisibility(R.id.widget_homework_hint,compact?View.VISIBLE:View.GONE);views.setViewVisibility(R.id.widget_secondary_list,compact?View.GONE:View.VISIBLE);views.setTextViewText(R.id.widget_homework,homework?"当天课程":"作业 · "+HomeworkDisplay.visible(c).length()+"项");if(compact){if(homework){java.time.LocalDate selected=WidgetOptions.date(c,id,now);java.util.List<WeekTable.Item> classes=WidgetDayTable.items(c,selected);views.setTextViewText(R.id.widget_homework,"课程 · "+classes.size()+"项");views.setTextViewText(R.id.widget_homework_hint,classes.isEmpty()?"这一天没有课程":WidgetData.detail(classes.get(0),now)+" · "+classes.get(0).event.optString("title"));}else{String hint=data.hint;if(Scanner.running()||WidgetCheckJob.pending(c))hint=Store.prefs(c).getString("widgetProgress","正在检查，保留上次结果");views.setTextViewText(R.id.widget_homework_hint,hint);}}else WidgetLists.bind(c,views,id,R.id.widget_secondary_list,!homework,now);}

  if(homework&&secondary){if(HomeworkDisplay.visible(c).length()==0)views.setViewVisibility(R.id.widget_primary_list,View.GONE);WidgetDateNav.bind(c,views,id,false,true,now);if(height<330)views.setViewVisibility(R.id.widget_date,View.GONE);}
  WidgetMenu.visibility(c,views,id);
  return views;
 }
 static void addRow(Context c,RemoteViews views,String title,String detail,PendingIntent action,int height,boolean schedule){RemoteViews row=new RemoteViews(c.getPackageName(),R.layout.rain_widget_row);row.setTextViewText(R.id.widget_course_title,title);row.setTextViewText(R.id.widget_course_detail,detail);if(height<190&&schedule)row.setViewVisibility(R.id.widget_course_detail,View.GONE);if(height<190){int pad=(int)(4*c.getResources().getDisplayMetrics().density);row.setViewPadding(R.id.widget_course_area,pad,pad,pad,pad);}row.setOnClickPendingIntent(R.id.widget_course_area,action);views.addView(R.id.widget_rows,row);}
 static void bindSchedule(Context c,RemoteViews views,int button){views.setOnClickPendingIntent(button,tick(c));views.setTextViewText(button,"刷新课表");views.setContentDescription(button,"刷新课表：更新本机课程和日程显示");views.setBoolean(button,"setEnabled",true);}
 static void bindHomework(Context c,RemoteViews views,int button){boolean checking=Scanner.running()||WidgetCheckJob.pending(c),failed=Store.prefs(c).getString("status","").startsWith("检查失败");views.setOnClickPendingIntent(button,!checking&&failed?issue(c):checkHomework(c));views.setTextViewText(button,checking?"检查中…":failed?"查看问题":"刷新作业");views.setContentDescription(button,checking?"正在后台检查作业":failed?"查看作业检查问题":"刷新作业：后台联网检查最新作业");views.setBoolean(button,"setEnabled",!checking);}
 static void updateAll(Context c){try{AppWidgetManager manager=AppWidgetManager.getInstance(c);int[] ids=manager.getAppWidgetIds(new ComponentName(c,RainWidget.class));AlarmManager alarm=c.getSystemService(AlarmManager.class);alarm.cancel(tick(c));WidgetOptions.prune(c,ids);if(ids.length==0)return;long now=System.currentTimeMillis();for(int id:ids){Bundle options=manager.getAppWidgetOptions(id);int height=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,180);int portrait=options.getInt(AppWidgetManager.OPTION_APPWIDGET_MAX_HEIGHT,height);manager.updateAppWidget(id,new RemoteViews(views(c,id,height,now),views(c,id,portrait,now)));}manager.notifyAppWidgetViewDataChanged(ids,R.id.widget_day_pages);if(Build.VERSION.SDK_INT<31){manager.notifyAppWidgetViewDataChanged(ids,R.id.widget_menu_options);manager.notifyAppWidgetViewDataChanged(ids,R.id.widget_primary_list);manager.notifyAppWidgetViewDataChanged(ids,R.id.widget_secondary_list);}WidgetData.Snapshot data=WidgetData.build(Agenda.all(c),HomeworkDisplay.visible(c),Store.prefs(c).getLong("last",0),now);alarm.set(AlarmManager.RTC,Math.max(now+1000,(Scanner.running()||WidgetCheckJob.pending(c))?Math.min(data.next,now+60000):data.next),tick(c));}catch(Exception ignored){}}
 public void onUpdate(Context c,AppWidgetManager manager,int[] ids){updateAll(c);}
 public void onEnabled(Context c){updateAll(c);}
 public void onDisabled(Context c){c.getSystemService(AlarmManager.class).cancel(tick(c));}
 public void onDeleted(Context c,int[] ids){WidgetOptions.remove(c,ids);}
 public void onAppWidgetOptionsChanged(Context c,AppWidgetManager manager,int id,Bundle options){super.onAppWidgetOptionsChanged(c,manager,id,options);updateAll(c);}
 public void onReceive(Context c,Intent intent){super.onReceive(c,intent);if(REFRESH.equals(intent.getAction()))updateAll(c);else if(CHECK.equals(intent.getAction()))WidgetCheckJob.request(c);else if(MENU.equals(intent.getAction())){int id=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(id>0&&info!=null&&new ComponentName(c,RainWidget.class).equals(info.provider)){WidgetMenu.toggle(c,id);}}else if(SWITCH.equals(intent.getAction())){int id=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(id<=0||info==null||!new ComponentName(c,RainWidget.class).equals(info.provider)||!WidgetOptions.menu(c,id))return;int mode=intent.getIntExtra("mode",-1),style=intent.getIntExtra("style",-1);if(WidgetOptions.valid(mode)&&style==-1){WidgetOptions.menu(c,id,false);WidgetOptions.save(c,id,mode);}else if(mode==-1&&(style==0||style==1)){WidgetOptions.menu(c,id,false);WidgetOptions.saveStyle(c,id,style);updateAll(c);}}else if(WidgetDayTable.NAVIGATE.equals(intent.getAction())){int id=intent.getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1),delta=intent.getIntExtra("delta",0);if(delta!=0&&Math.abs(delta)!=1&&Math.abs(delta)!=7)return;AppWidgetProviderInfo info=AppWidgetManager.getInstance(c).getAppWidgetInfo(id);if(info!=null&&new ComponentName(c,RainWidget.class).equals(info.provider)){if(WidgetOptions.menu(c,id))return;boolean week=!WidgetOptions.homeworkFirst(WidgetOptions.mode(c,id))&&WidgetOptions.style(c,id)==1;if(delta!=0&&Math.abs(delta)!=(week?7:1))return;WidgetOptions.moveDay(c,id,delta,System.currentTimeMillis());updateAll(c);}}}
 static void pin(Activity a){AppWidgetManager manager=AppWidgetManager.getInstance(a);try{if(manager.isRequestPinAppWidgetSupported()){boolean sent=manager.requestPinAppWidget(new ComponentName(a,RainWidget.class),null,null);if(sent){Toast.makeText(a,"请在桌面弹窗中确认添加小组件",Toast.LENGTH_LONG).show();return;}}}catch(RuntimeException ignored){}new AlertDialog.Builder(a).setTitle("添加桌面小组件").setMessage("在桌面长按空白处，找到“小组件”或“窗口小工具”，选择“待课 · 作业与课表”。添加后可长按调整大小。“刷新课表”更新本机课程显示；“刷新作业”在后台联网检查并更新结果；出现问题时点“查看问题”打开应用处理。").setPositiveButton("知道了",null).show();}
}
